	<section id="inquiry" class="scroll-mt-24"><div class="mx-auto grid max-w-7xl gap-12 px-4 py-20 sm:px-6 lg:grid-cols-[0.8fr_1.2fr] lg:items-start lg:px-8 lg:py-28"><div><p class="text-sm font-semibold text-amber-400">شروع بررسی</p><h2 class="mt-3 text-3xl font-bold leading-[1.45] text-white sm:text-4xl">نیاز فنی پروژه‌تان را با رومونت بررسی کنید</h2><p class="mt-5 text-sm leading-8 text-neutral-400">شرح مسئله و نیازمندی‌های اولیه را ارسال کنید. لطفاً رمز عبور، کلید API یا اطلاعات محرمانه را در این فرم وارد نکنید.</p><div class="mt-8 flex flex-wrap gap-5 text-sm"><?php if ( $website_url ) : ?><a href="<?php echo esc_url( $website_url ); ?>" class="text-amber-400 hover:text-amber-300">طراحی سایت</a><?php endif; ?><?php if ( $woocommerce_url ) : ?><a href="<?php echo esc_url( $woocommerce_url ); ?>" class="text-amber-400 hover:text-amber-300">توسعه ووکامرس</a><?php endif; ?><?php if ( $support_url ) : ?><a href="<?php echo esc_url( $support_url ); ?>" class="text-amber-400 hover:text-amber-300">پشتیبانی وردپرس</a><?php endif; ?><?php if ( $portfolio_url ) : ?><a href="<?php echo esc_url( $portfolio_url ); ?>" class="text-amber-400 hover:text-amber-300">نمونه‌کارها</a><?php endif; ?><?php if ( $contact_url ) : ?><a href="<?php echo esc_url( $contact_url ); ?>" class="text-amber-400 hover:text-amber-300">ارتباط با رومونت</a><?php endif; ?><?php if ( $about_url ) : ?><a href="<?php echo esc_url( $about_url ); ?>" class="text-amber-400 hover:text-amber-300">درباره رومونت</a><?php endif; ?></div></div>
		<form xyz-on:submit.prevent="submitCustomDevelopmentRequest()" class="rounded-2xl border border-white/10 bg-white/[0.03] p-6 sm:p-8"><div xyz-show="!submitSuccess" class="space-y-5"><div class="grid gap-5 sm:grid-cols-2"><label class="block text-sm text-neutral-300">نام و نام خانوادگی *<input type="text" xyz-model="customerName" required autocomplete="name" class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none focus:border-amber-400"></label><label class="block text-sm text-neutral-300">شماره تماس *<input type="tel" xyz-model="customerPhone" required autocomplete="tel" inputmode="tel" dir="ltr" class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-left text-sm text-white outline-none focus:border-amber-400"></label></div><label class="block text-sm text-neutral-300">نام شرکت یا کسب‌وکار <span class="text-neutral-500">(اختیاری)</span><input type="text" xyz-model="businessName" class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none focus:border-amber-400"></label><label class="block text-sm text-neutral-300">آدرس سایت <span class="text-neutral-500">(اختیاری)</span><input type="url" xyz-model="siteUrl" dir="ltr" class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-left text-sm text-white outline-none focus:border-amber-400" placeholder="https://example.com"></label><label class="block text-sm text-neutral-300">نوع درخواست *<select xyz-model="requestType" class="mt-2 w-full rounded-xl border border-white/10 bg-[#11131c] px-4 py-3 text-sm text-white outline-none focus:border-amber-400"><option>توسعه افزونه اختصاصی</option><option>طراحی قالب اختصاصی</option><option>توسعه ووکامرس</option><option>اتصال API و سرویس‌های خارجی</option><option>توسعه قابلیت اختصاصی وردپرس</option><option>توسعه یا اصلاح افزونه موجود</option><option>سایر موارد</option></select></label><label class="block text-sm text-neutral-300">توضیحات فنی و نیازمندی‌های پروژه *<textarea xyz-model="notes" required rows="6" class="mt-2 w-full rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm leading-7 text-white outline-none focus:border-amber-400"></textarea></label><p xyz-show="submitError" xyz-text="submitError" class="text-sm leading-6 text-rose-300" style="display:none"></p><button type="submit" xyz-bind:disabled="isSubmitting" class="inline-flex min-h-12 w-full items-center justify-center rounded-xl bg-amber-500 text-sm font-bold text-black transition hover:bg-amber-400 disabled:cursor-not-allowed disabled:opacity-70"><span xyz-show="!isSubmitting">ارسال درخواست بررسی پروژه</span><span xyz-show="isSubmitting" style="display:none">در حال ارسال...</span></button></div><div xyz-show="submitSuccess" class="py-8 text-center" style="display:none"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500/10 text-emerald-400" aria-hidden="true">✓</div><h3 class="mt-5 text-xl font-bold text-white">درخواست شما ثبت شد</h3><p class="mt-3 text-sm leading-7 text-neutral-300" xyz-text="successMessage"></p></div></form>
	</div></section>
</main>
